 public static final class Registration {@SubscribeEvent public static void register(net.neoforged.neoforge.registries.RegisterEvent event){if(!enabled())return;var id=ResourceLocation.fromNamespaceAndPath("vandorlabs","large_door_lifecycle_fixture");event.register(Registries.BLOCK,h->{block=new Fixture();h.register(id,block);LargeDoorGushChecks.replaceable=new LargeDoorGushChecks.Replaceable();h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","large_gush_replaceable_fixture"),LargeDoorGushChecks.replaceable);power=new LargeDoorControlChecks.Power();h.register(ResourceLocation.fromNamespaceAndPath("vandorlabs","large_door_power_fixture"),power);});event.register(Registries.ITEM,h->{item=new NativeLargeDoorItem(block,new Item.Properties());h.register(id,item);});event.register(Registries.BLOCK_ENTITY_TYPE,h->{type=BlockEntityType.Builder.<NativeLargeDoorEntity>of((pos,state)->new Counting(pos,state),block).build(null);h.register(id,type);});event.register(Registries.MENU,h->{menus=net.neoforged.neoforge.common.extensions.IMenuTypeExtension.create((window,inventory,buf)->new NativeDoorMenu(menus,window,inventory,buf.readBlockPos()));h.register(id,menus);});}}
